// Generate branch name and prepare context
const featureTicket = $input.first().json.feature_ticket;
const timestamp = Date.now();
const branchName = `ai-agent/${featureTicket.toLowerCase().replace(/[^a-z0-9]+/g, '-').substring(0, 50)}-${timestamp}`;

// Get repository structure
const repoTree = $('Get Repository Structure').item.json.tree || [];
const fileStructure = repoTree
  .filter(item => item.type === 'blob')
  .map(item => item.path)
  .join('\n');

return {
  json: {
    branch_name: branchName,
    feature_ticket: featureTicket,
    repo_owner: $('Set Input Parameters').item.json.repo_owner,
    repo_name: $('Set Input Parameters').item.json.repo_name,
    base_sha: $('Get Base Branch SHA').item.json.object.sha,
    base_branch: $('Set Input Parameters').item.json.base_branch,
    default_branch: $('Get Repository Info').item.json.default_branch,
    repo_description: $('Get Repository Info').item.json.description,
    repo_language: $('Get Repository Info').item.json.language,
    file_structure: fileStructure,
    repo_topics: $('Get Repository Info').item.json.topics || []
  }
};

// Split the parsed response into individual file items for processing
const parsedResponse = $input.first().json.parsed_response;
const files = parsedResponse.files || [];
const branchData = $('Prepare Context').item.json;

const items = files.map(file => ({
  json: {
    file_path: file.path,
    file_content: file.content,
    file_action: file.action,
    file_reason: file.reason || '',
    branch_name: branchData.branch_name,
    repo_owner: branchData.repo_owner,
    repo_name: branchData.repo_name,
    pr_title: parsedResponse.pr_title,
    pr_description: parsedResponse.pr_description,
    implementation_plan: parsedResponse.implementation_plan,
    dependencies: JSON.stringify(parsedResponse.dependencies || []),
    base_branch: branchData.base_branch
  }
}));

return items;

